import wordsCsv from '../../../db/words/words.csv?raw'

// Mirrors public.words in db/words/schema.sql.
export interface Word {
  rank: number
  word: string
  length: number
  letters: string
  letterMask: number
  hand: 'left' | 'right' | 'both'
  bigrams: string[]
  alternationCount: number
  rollCount: number
  rowJumpCount: number
  sameFingerCount: number
  repeatCount: number
}

// Rows are generated by scripts/build-words.mjs: no commas inside fields except the quoted "{..}" bigram array.
function parseRow(line: string): Word {
  const [before, bigramField, after] = line.split('"')
  const [rank, word, length, letters, letterMask, hand] = before.split(',')
  const counts = after.split(',').slice(1).map(Number)
  return {
    rank: Number(rank),
    word,
    length: Number(length),
    letters,
    letterMask: Number(letterMask),
    hand: hand as Word['hand'],
    bigrams: bigramField === '{}' ? [] : bigramField.slice(1, -1).split(','),
    alternationCount: counts[0],
    rollCount: counts[1],
    rowJumpCount: counts[2],
    sameFingerCount: counts[3],
    repeatCount: counts[4],
  }
}

export const words: Word[] = wordsCsv.trim().split('\n').slice(1).map(parseRow)
